import {BASE_KEY,LEARN_KEY,gradeBaseline} from './learning-core.mjs';
async function updateScore(){let baseline;try{baseline=JSON.parse(localStorage.getItem(BASE_KEY));}catch{return;}if(baseline?.status!=='submitted')return;const r=await fetch('base-words.json');if(!r.ok)return;const deck=await r.json();let overrides={};try{overrides=JSON.parse(localStorage.getItem(LEARN_KEY))?.overrides||{};}catch{}const rows=gradeBaseline(baseline,deck,overrides),correct=rows.filter(x=>x.result==='correct').length,pending=rows.filter(x=>x.result==='pending').length;let panel=document.getElementById('autoScore');if(!panel){panel=document.createElement('div');panel.id='autoScore';panel.className='note';document.getElementById('summary').after(panel);}panel.replaceChildren();const title=document.createElement('h2');title.textContent=`规则初评分：${correct} / 20${pending?'，另有'+pending+'词待核对':'（'+Math.round(correct/20*100)+'%）'}`;const p=document.createElement('p');p.textContent='错词与眼熟词可以加入专项复习。规则不认识的表达不会直接判错，可在训练室核对和纠正判分。';panel.append(title,p);}
window.addEventListener('vocabulary-submitted',()=>updateScore().catch(()=>{}));updateScore().catch(()=>{});
